timestamp=$(date +%Y%m%d-%H%M%S)
backup_root="expected-backup-${timestamp}"
echo "Creating backup at: $backup_root" >&2
mkdir -p "$backup_root"

updated=0
skipped=0

backup_and_update() {
  local exp="$1"; shift
  local out="$2"; shift
  if [[ ! -f "$exp" || ! -f "$out" ]]; then
    echo "[skip] Missing file for pair: $exp | $out" >&2
    ((skipped++))
    return
  fi
  local dest="$backup_root/$exp"
  local dest_dir
  dest_dir=$(dirname "$dest")
  if [[ ! -f "$dest" ]]; then
    mkdir -p "$dest_dir"
    cp -p "$exp" "$dest"
  fi
  cp -p "$out" "$exp"
  echo "[upd] $exp <- $out" >&2
  ((updated++))
}

